'use strict';

// MODULES //

var dcabs1 = require( '@stdlib/blas/base/dcabs1' );


// MAIN //

/**
* Finds the index of the first element having the maximum absolute value.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Complex128Array} zx - input array
* @param {integer} strideX - `zx` stride length
* @param {NonNegativeInteger} offsetX - starting index for `zx`
* @returns {integer} index value
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var zx = new Complex128Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
*
* var idx = izamax( zx.length, zx, 1, 0 );
* // returns 1
*/
function izamax( N, zx, strideX, offsetX ) {
	var zmax;
	var idx;
	var ix;
	var v;
	var i;

	if ( N < 1 ) {
		return -1;
	}
	idx = 0;
	if ( N === 1 ) {
		return idx;
	}
	zmax = dcabs1( zx.get( offsetX ) );
	ix = offsetX + strideX;
	for ( i = 1; i < N; i++ ) {
		v = dcabs1( zx.get( ix ) );
		if ( v > zmax ) {
			idx = i;
			zmax = v;
		}
		ix += strideX;
	}
	return idx;
}


// EXPORTS //

module.exports = izamax;
